using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.Net.Http", "System.IO", "System.Data", "System.Text.Json",
    ];

    [Fact]
    public void Domain_does_not_depend_on_other_layers()
    {
        AssertNoDependencies(typeof(Money), [ApplicationNamespace, InfrastructureNamespace]);
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        AssertNoDependencies(typeof(AuthorizePayment), [InfrastructureNamespace]);
    }

    [Fact]
    public void Domain_and_application_do_not_use_technical_namespaces()
    {
        AssertNoDependencies(typeof(Money), TechnicalNamespaces);
        AssertNoDependencies(typeof(AuthorizePayment), TechnicalNamespaces);
    }

    [Fact]
    public void Layers_are_the_ones_these_rules_inspect()
    {
        Assert.NotEmpty(Types.InAssembly(typeof(Money).Assembly).That().ResideInNamespace(DomainNamespace).GetTypes());
        Assert.NotEmpty(Types.InAssembly(typeof(AuthorizePayment).Assembly).That().ResideInNamespace(ApplicationNamespace).GetTypes());
        Assert.NotEmpty(Types.InAssembly(typeof(FileSystemReceiptStore).Assembly).That().ResideInNamespace(InfrastructureNamespace).GetTypes());
    }

    private static void AssertNoDependencies(Type layerMarker, string[] forbidden)
    {
        var result = Types.InAssembly(layerMarker.Assembly)
            .ShouldNot()
            .HaveDependencyOnAny(forbidden)
            .GetResult();

        Assert.True(result.IsSuccessful,
            $"Forbidden dependency on {string.Join(", ", forbidden)} from: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }
}
